import React from 'react';

const WebLanding: React.FC = () => {
  const goToAuth = () => {
    try {
      const ret = encodeURIComponent(window.location.pathname + (window.location.search || ''));
      const u = new URL(window.location.href);
      u.hash = '#/webauth?return=' + ret;
      window.location.replace(u.toString());
    } catch {
      try { window.location.hash = '#/webauth'; } catch {}
    }
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 'var(--sp-spacing-md, 24px)', background: 'var(--sp-bg-secondary, #f6f7fb)', color: 'var(--sp-text-primary, #111)' }}>
      <div style={{ background: 'var(--sp-surface, #fff)', border: '1px solid var(--sp-border-color, #e5e7eb)', borderRadius: 12, padding: 'var(--sp-spacing-md, 24px)', maxWidth: 520, width: '100%', textAlign: 'center', boxSizing: 'border-box' }}>
        <div style={{ fontSize: 28, marginBottom: 'var(--sp-spacing-xs, 8px)' }}>SoulPulse</div>
        <div style={{ fontSize: 14, color: 'var(--sp-text-secondary, #6b7280)', marginBottom: 'var(--sp-spacing-sm, 16px)' }}>
          Для доступа к веб‑интерфейсу выполните вход.
        </div>
        <button onClick={goToAuth} style={{ background: 'var(--sp-primary, #6366f1)', color: '#fff', border: 'none', borderRadius: 8, padding: '10px 16px', cursor: 'pointer' }}>
          Перейти к входу
        </button>
      </div>
    </div>
  );
};

export default WebLanding;


